// Ticket, VM and task from the webhook body, or a fictional sample: ticket T-1042 asks to renew the TLS certificate of proxy-edge-01 (the sample backup is 30 h old, so the runbook takes a backup first).
// A real call must say approved: true. Without it the runbook stops after the check and changes nothing.
const TASK_KEYS = ["cert", "patch", "disk", "backup", "unreachable", "cpu", "mem"];
const b = $input.first().json.body;
const sample = {"id":"vm-25","name":"proxy-edge-01","role":"Edge proxy","env":"prod","site":"Amsterdam","os":"Ubuntu 22.04","cpuPct":24,"memPct":39,"diskPct":35,"backupAgeHours":30,"patchLagDays":16,"uptimeDays":66,"reachable":true,"vcpu":4,"ramGb":16,"certExpiresInDays":5};
const src = b && b.vm ? b : { ticket: { id: 'T-1042', title: 'Renew TLS certificate of proxy-edge-01' }, vm: sample, task: 'cert', approved: true };
const vm = { env: 'prod', reachable: true, ...src.vm };
const ticket = { id: String((src.ticket && src.ticket.id) || 'no ticket').slice(0, 40), title: String((src.ticket && src.ticket.title) || '').slice(0, 120) };
const task = TASK_KEYS.includes(src.task) ? src.task : null;
return [{ json: { ticket, vm, task, approved: src.approved === true, log: [] } }];

function assess(vm, rules) {
  const reasons = [];
  const add = (level, text, key) => reasons.push({ level, text, key });
  if (!vm.reachable) add('red', 'Not reachable: the VM does not answer monitoring checks', 'unreachable');
  else {
    const metric = (field, label, unit, key) => {
      const v = vm[field], r = rules[field];
      if (v === null || v === undefined) return;
      if (r.appliesTo && r.appliesTo !== vm.env) return;
      if (field === 'certExpiresInDays') {
        if (v <= r.red) add('red', `${label} ${v}${unit} (red up to ${r.red}${unit})`, key);
        else if (v <= r.yellow) add('yellow', `${label} ${v}${unit} (yellow up to ${r.yellow}${unit})`, key);
      } else if (v >= r.red) add('red', `${label} ${v}${unit} (red from ${r.red}${unit})`, key);
      else if (v >= r.yellow) add('yellow', `${label} ${v}${unit} (yellow from ${r.yellow}${unit})`, key);
    };
    metric('cpuPct', 'CPU', ' %', 'cpu'); metric('memPct', 'Memory', ' %', 'mem'); metric('diskPct', 'Disk', ' %', 'disk');
    metric('backupAgeHours', 'Last backup', ' h ago', 'backup'); metric('patchLagDays', 'Security patch missing for', ' days', 'patch');
    metric('certExpiresInDays', 'TLS certificate expires in', ' days', 'cert');
  }
  const status = reasons.some((r) => r.level === 'red') ? 'red' : reasons.length ? 'yellow' : 'green';
  reasons.sort((a, b) => (a.level === b.level ? 0 : a.level === 'red' ? -1 : 1));
  return { status, reasons };
}

const RULES = {"cpuPct":{"yellow":75,"red":90},"memPct":{"yellow":85,"red":95},"diskPct":{"yellow":85,"red":95},"backupAgeHours":{"yellow":24,"red":48,"appliesTo":"prod"},"patchLagDays":{"yellow":14,"red":30},"certExpiresInDays":{"yellow":30,"red":7}};
const TASKS = {"cert":{"title":"Renew TLS certificate","steps":["Create the signing request","Check the chain and the services that use the certificate","Install in the maintenance window after approval"],"reboot":false,"approver":"Security","fix":{"certExpiresInDays":365}},"patch":{"title":"Install security patch","steps":["Check maintenance window and redundancy","Patch the twin or standby first","Restart and run the health check"],"reboot":true,"approver":"Change board","fix":{"patchLagDays":0,"uptimeDays":0}},"disk":{"title":"Free up disk space","steps":["Find the largest directories and old logs","Propose archive, clean-up or resize","Run after approval, then measure again"],"reboot":false,"approver":"Service owner","fix":{"diskPct":61}},"backup":{"title":"Catch up the backup","steps":["Check the backup job and its last error","Start a backup run","Verify the restore point"],"reboot":false,"approver":"Backup owner","fix":{"backupAgeHours":1}},"unreachable":{"title":"Check an unreachable VM","steps":["Ping, port and hypervisor status","Look at the console and recent changes","Propose a restart, never restart without approval"],"reboot":true,"approver":"On-call","fix":{"reachable":true,"cpuPct":20,"memPct":35,"diskPct":40,"uptimeDays":0}},"cpu":{"title":"Analyse the CPU peak","steps":["Find the process behind the peak","Compare with the twin VM","Propose scaling or a fix, with approval"],"reboot":false,"approver":"Service owner","fix":{"cpuPct":45}},"mem":{"title":"Check memory pressure","steps":["List the largest memory users","Look for leaks and restart candidates","Propose a restart or more RAM, with approval"],"reboot":false,"approver":"Service owner","fix":{"memPct":60}}};
// Step 1: measure the VM again and check that the task is still needed (the ticket may be old).
const s = $input.first().json;
const a = assess(s.vm, RULES);
const needed = !!s.task && a.reasons.some((r) => r.key === s.task);
const why = !s.task ? 'unknown task' : needed ? a.reasons.find((r) => r.key === s.task).text : 'the check no longer shows the reason';
return [{ json: { ...s, before: { status: a.status, reasons: a.reasons }, needed, go: needed && s.approved, log: [...s.log, `1 Check: ${s.vm.name} is ${a.status}; ${s.task || 'task'} ${needed ? 'is needed (' + why + ')' : 'is not needed (' + why + ')'}`] } }];

// The runbook stops here: nothing was changed.
const s = $input.first().json;
const reason = !s.task ? 'unknown task' : !s.needed ? 'task no longer needed' : 'not approved yet';
return [{ json: { ...s, result: 'not run', reason, log: [...s.log, 'Stopped: ' + reason + '. Nothing was changed.'] } }];

// Step 2: backup before the change (simulated). Production VMs need a restore point that is at most 24 h old.
const s = $input.first().json;
const rp = 'RP-' + s.vm.id + '-' + String(s.vm.backupAgeHours) + 'h';
return [{ json: { ...s, vm: { ...s.vm, backupAgeHours: 0 }, backup: { done: true, restorePoint: rp, verified: true }, log: [...s.log, `2 Backup: last backup was ${s.vm.backupAgeHours} h old, new restore point ${rp} created and verified (simulated)`] } }];

// Step 2: no backup needed.
const s = $input.first().json;
return [{ json: { ...s, backup: { done: false, reason: s.vm.env !== 'prod' ? 'not a production VM' : 'restore point is recent enough' }, log: [...s.log, '2 Backup: not needed (' + (s.vm.env !== 'prod' ? 'not a production VM' : 'restore point is ' + s.vm.backupAgeHours + ' h old') + ')'] } }];

