// Step 4: measure the VM again. The task counts as done only if its reason is gone.
const s = $input.first().json;
const a = assess(s.vm, RULES);
const cleared = !a.reasons.some((r) => r.key === s.task);
return [{ json: { ...s, after: { status: a.status, reasons: a.reasons }, result: cleared ? 'done' : 'failed', log: [...s.log, `4 Verify: ${s.vm.name} is ${a.status}; reason ${s.task} ${cleared ? 'cleared' : 'still present'}`] } }];

// Report for the operator and the ticket. This is what the ticket gets as the final comment.
const s = $input.first().json;
const out = {
  ticket: s.ticket, vm: s.vm.name, task: s.task, result: s.result, reason: s.reason || null,
  statusBefore: s.before && s.before.status, statusAfter: s.after ? s.after.status : (s.before && s.before.status),
  backup: s.backup || null, log: s.log,
};
out.digest = s.result === 'done'
  ? `Ticket ${s.ticket.id}: ${s.vm.name} checked, ${s.backup && s.backup.done ? 'restore point ' + s.backup.restorePoint + ' taken, ' : ''}task "${s.applied.title}" applied and verified. Status ${out.statusBefore} -> ${out.statusAfter}. Simulated: no real VM was changed.`
